CREATE TABLE IF NOT EXISTS instansi (kode VARCHAR(64) PRIMARY KEY, nama VARCHAR(255) NOT NULL, peran_sop TEXT, admin_data TINYINT NOT NULL DEFAULT 0) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pengguna (email VARCHAR(255) PRIMARY KEY, surel_notifikasi VARCHAR(255), nama VARCHAR(255), jabatan VARCHAR(255), instansi VARCHAR(64), peran ENUM('pic','verifikator','super') NOT NULL, aktif TINYINT NOT NULL DEFAULT 1, terima_email TINYINT NOT NULL DEFAULT 1, dibuat VARCHAR(40) NOT NULL, terakhir_masuk VARCHAR(40)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kredensial (email VARCHAR(255) PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, versi BIGINT NOT NULL DEFAULT 1, diubah VARCHAR(40) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wali_aturan (id BIGINT PRIMARY KEY AUTO_INCREMENT, dataset VARCHAR(64) NOT NULL, kolom VARCHAR(128) NOT NULL DEFAULT '*', instansi VARCHAR(64) NOT NULL, UNIQUE KEY uq_wali (dataset,kolom,instansi)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS baris (id BIGINT PRIMARY KEY AUTO_INCREMENT, dataset VARCHAR(64) NOT NULL, kunci VARCHAR(255) NOT NULL, instansi VARCHAR(64), data LONGTEXT NOT NULL, status_data ENUM('sementara','terverifikasi','resmi') NOT NULL DEFAULT 'sementara', nomor_ba VARCHAR(255), tanggal_mutakhir VARCHAR(40), terbit VARCHAR(8) NOT NULL DEFAULT '', terbit_data LONGTEXT, terbit_meta LONGTEXT, hapus TINYINT NOT NULL DEFAULT 0, versi INT NOT NULL DEFAULT 1, diubah_oleh VARCHAR(255), diubah_pada VARCHAR(40) NOT NULL, UNIQUE KEY uq_baris (dataset,kunci), KEY ix_baris_ds (dataset,terbit)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usulan (id BIGINT PRIMARY KEY AUTO_INCREMENT, dataset VARCHAR(64) NOT NULL, baris_id BIGINT, kunci VARCHAR(255), aksi ENUM('ubah','tambah','hapus') NOT NULL, data_baru LONGTEXT NOT NULL, instansi VARCHAR(64) NOT NULL, periode VARCHAR(40) NOT NULL, status ENUM('draft','diajukan','dikembalikan','terverifikasi','ditolak','ditetapkan') NOT NULL DEFAULT 'draft', oleh VARCHAR(255) NOT NULL, dibuat VARCHAR(40) NOT NULL, diajukan_pada VARCHAR(40), diverifikasi_oleh VARCHAR(255), diverifikasi_pada VARCHAR(40), catatan TEXT, KEY ix_usulan_st (status,periode)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS konfirmasi (periode VARCHAR(40) NOT NULL, instansi VARCHAR(64) NOT NULL, oleh VARCHAR(255) NOT NULL, tanggal VARCHAR(40) NOT NULL, catatan TEXT, PRIMARY KEY (periode,instansi)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifikasi (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL, judul VARCHAR(255) NOT NULL, isi TEXT, tipe VARCHAR(40), tautan VARCHAR(255), dibaca TINYINT NOT NULL DEFAULT 0, dibuat VARCHAR(40) NOT NULL, email_status VARCHAR(80), KEY ix_notif (email,dibaca)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS riwayat (id BIGINT PRIMARY KEY AUTO_INCREMENT, waktu VARCHAR(40) NOT NULL, email VARCHAR(255), peran VARCHAR(40), aksi VARCHAR(80) NOT NULL, dataset VARCHAR(64), objek VARCHAR(255), ringkas TEXT) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pengingat_log (kunci VARCHAR(255) PRIMARY KEY, waktu VARCHAR(40) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mitra_kontak (kode VARCHAR(80) PRIMARY KEY, enc LONGTEXT NOT NULL, dibuat VARCHAR(40) NOT NULL, diubah_oleh VARCHAR(255)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS permintaan_data (nomor VARCHAR(80) PRIMARY KEY, kategori VARCHAR(255), status VARCHAR(40) NOT NULL DEFAULT 'masuk', enc LONGTEXT NOT NULL, dibuat VARCHAR(40) NOT NULL, diubah VARCHAR(40), petugas VARCHAR(255)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pendaftaran_mitra (nomor VARCHAR(80) PRIMARY KEY, saluran VARCHAR(255), penerima VARCHAR(64), status VARCHAR(40) NOT NULL DEFAULT 'masuk', kode_mitra VARCHAR(80), enc LONGTEXT NOT NULL, dibuat VARCHAR(40) NOT NULL, diubah VARCHAR(40), petugas VARCHAR(255)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ratelimit (kunci VARCHAR(255) PRIMARY KEY, n INT NOT NULL, jendela VARCHAR(40) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_code (email VARCHAR(255) PRIMARY KEY, code_hash VARCHAR(64) NOT NULL, expires_at BIGINT NOT NULL, attempts INT NOT NULL DEFAULT 0, sent_at BIGINT NOT NULL, window_start BIGINT NOT NULL, sent_count INT NOT NULL DEFAULT 1) DEFAULT CHARSET=utf8mb4;
